// skills/band-app.md, "Keep the screen lit": the band stops at 15 seconds.
var SCREEN_ON_SECONDS = 120;

var bleReady = false;

function holdScreen() {
  try {
    if (typeof hmSetting !== 'undefined' && hmSetting.setBrightScreen) {
      hmSetting.setBrightScreen(SCREEN_ON_SECONDS);
    }
  } catch (e) {
    // A firmware without the call must not take the page down.
  }
}

// Return to this page when the band wakes, not to the watch face.
function keepPageOnWake() {
  try {
    if (typeof hmApp !== 'undefined' && hmApp.setScreenKeep) {
      hmApp.setScreenKeep(true);
    }
  } catch (e) {
    // A firmware without the call must not take the page down.
  }
}

function releaseScreen() {
  try {
    if (typeof hmSetting !== 'undefined' && hmSetting.setBrightScreenCancel) {
      hmSetting.setBrightScreenCancel();
    }
  } catch (e) {
    // Throwing here helps nobody.
  }
}

// skills/zepp-os-app-build.md, "Open BLE lazily": a throw during onInit
// leaves the page half built.
function ensureBle() {
  if (bleReady) {
    return true;
  }
  try {
    if (typeof hmBle === 'undefined') {
      return false;
    }
    hmBle.createConnect(function (index, data, size) {});
    bleReady = true;
  } catch (e) {
    bleReady = false;
  }
  return bleReady;
}

function emit(bytes) {
  try {
    if (!ensureBle()) {
      return false;
    }
    if (hmBle.connectStatus() !== true) {
      return false;
    }
    var buf = new Uint8Array(bytes);
    hmBle.send(buf.buffer, buf.byteLength);
    return true;
  } catch (e) {
    return false;
  }
}

// One function call per button, so each click handler keeps its own button.
function makeButton(b) {
  var props = {
    x: b.x,
    y: b.y,
    w: b.w,
    h: b.h,
    radius: b.radius,
    text: b.text,
    text_size: b.textSize,
    color: 0xffffff,
    click_func: function () {
      emit(b.bytes);
      holdScreen();
    }
  };
  if (b.image) {
    props.normal_src = b.image;
    props.press_src = b.pressImage;
  } else {
    props.normal_color = b.color;
    props.press_color = b.pressColor;
  }
  return hmUI.createWidget(hmUI.widget.BUTTON, props);
}

